"""Write static/js/crest-table.js (US-179 AE A2, E2d).

The crest factors are computed by the same JS the level check runs
(crest-plan.js), in headless Chromium, and stored as constants.
crest.test.js recomputes them in CI.

    nix develop --command python src/web-rc/tools/gen_crest_table.py
"""

import functools
import http.server
import json
import threading
from pathlib import Path

from playwright.sync_api import sync_playwright

WEB_RC_ROOT = Path(__file__).resolve().parent.parent
OUT = WEB_RC_ROOT / "static" / "js" / "crest-table.js"

HEADER = """\
// crest-table.js -- GENERATED by tools/gen_crest_table.py. Do not edit.
//
// Level-noise RMS, peak and crest factor (dB) per band and seed at 48 kHz,
// over the first LEVEL_NOISE.CREST_SECONDS of each stream (AE A2, E2d).
// crest.test.js recomputes every entry.

function deepFreeze(o) {
  for (const v of Object.values(o)) {
    if (typeof v === "object" && v !== null) deepFreeze(v);
  }
  return Object.freeze(o);
}

export const CREST_TABLE = deepFreeze("""


class _Handler(http.server.SimpleHTTPRequestHandler):
    extensions_map = {
        **http.server.SimpleHTTPRequestHandler.extensions_map,
        ".js": "text/javascript",
    }

    def log_message(self, format, *args):
        pass


def compute():
    handler = functools.partial(_Handler, directory=str(WEB_RC_ROOT))
    server = http.server.ThreadingHTTPServer(("127.0.0.1", 0), handler)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    url = f"http://127.0.0.1:{server.server_address[1]}"
    try:
        with sync_playwright() as p:
            browser = p.chromium.launch()
            page = browser.new_page()
            page.goto(f"{url}/tests/browser/runner.html?module=none")
            table = page.evaluate(
                "async (u) => (await import(u)).computeCrestTable()",
                f"{url}/static/js/crest-plan.js",
            )
            browser.close()
    finally:
        server.shutdown()
        server.server_close()
    return table


def render(table):
    body = json.dumps(table, indent=1)
    return HEADER + body + ");\n"


def main():
    OUT.write_text(render(compute()))
    print(f"wrote {OUT}")


if __name__ == "__main__":
    main()
